<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Hash,Storage};
use Illuminate\Http\UploadedFile;
use App\Models\{User,Post,Category,Tag,Comment,Media};
use App\Services\{ArticleContent,ArticleSchema,StaffAccounts,Editorial};

class EditorialReleaseTest extends TestCase {
 use RefreshDatabase;
 private function staff(string $role='administrator'):User { return User::factory()->create(['role'=>$role,'active'=>true,'is_admin'=>$role==='administrator']); }
 private function article(array $extra=[]):Post { return Post::create(array_merge(['title'=>'A thoughtful story','slug'=>'a-thoughtful-story','author_id'=>$this->staff()->id,'category_id'=>Category::firstOrCreate(['name'=>'Perspectives','slug'=>'perspectives'])->id,'body_html'=>'<h2 id="section-1">A useful beginning</h2><p>A thoughtful and meaningful article with enough real text to publish.</p>','status'=>'published','published_at'=>now()->subDay(),'content_updated_at'=>now()->subDay(),'schema_mode'=>'automatic','language'=>'en'],$extra)); }
 private function payload(Post $p,array $extra=[]):array { return array_merge(['title'=>$p->title,'slug'=>$p->slug,'author_id'=>$p->author_id,'category_id'=>$p->category_id,'body_html'=>$p->body_html,'status'=>'draft','schema_mode'=>'automatic','language'=>'en','version'=>$p->version],$extra); }
 public function test_existing_admin_password_login_and_logout_work():void {$u=$this->staff();$this->post('/login',['email'=>$u->email,'password'=>'password'])->assertRedirect('/admin');$this->assertAuthenticatedAs($u);$this->assertNotNull($u->fresh()->last_login_at);$this->post('/logout')->assertRedirect('/login');$this->assertGuest();}
 public function test_public_registration_is_always_404():void {DB::table('admin_setup')->update(['token_hash'=>hash('sha256','old-token'),'expires_at'=>now()->addDay()]);$this->get('/register')->assertNotFound();$this->post('/register',['setup_token'=>'old-token'])->assertNotFound();$this->actingAs($this->staff())->get('/register')->assertNotFound();}
 public function test_guest_all_admin_endpoints_require_login():void {foreach(['/admin','/admin/users','/admin/blogs','/admin/comments','/admin/taxonomy/tags'] as $path)$this->get($path)->assertRedirect('/login');$this->post('/admin/media')->assertRedirect('/login');}
 public function test_editor_cannot_manage_users_or_script_settings():void {$p=$this->article();$this->actingAs($this->staff('editor'));$this->get('/admin/users')->assertForbidden();$this->post('/admin/users',[])->assertForbidden();$this->post('/admin/blogs/'.$p->id.'/scripts',[])->assertForbidden();$this->post('/admin/scripts/disable')->assertForbidden();$this->get('/admin/blogs')->assertOk();}
 public function test_user_create_unique_email_optional_password_and_hidden_hash():void {$this->actingAs($this->staff());$data=['name'=>'Team member','email'=>'staff@example.test','password'=>'Long-Password123!','password_confirmation'=>'Long-Password123!','role'=>'editor','active'=>1];$this->post('/admin/users',$data)->assertRedirect();$u=User::where('email',$data['email'])->firstOrFail();$hash=$u->password;$this->assertTrue(Hash::check($data['password'],$hash));$this->post('/admin/users',$data)->assertSessionHasErrors('email');unset($data['password'],$data['password_confirmation']);$this->put('/admin/users/'.$u->id,$data)->assertRedirect();$this->assertSame($hash,$u->fresh()->password);$this->get('/admin/users/'.$u->id)->assertOk()->assertDontSee($hash);$this->assertArrayNotHasKey('password',$u->toArray());}
 public function test_last_admin_and_self_deactivation_are_protected():void {$u=$this->staff();$this->actingAs($u);$this->put('/admin/users/'.$u->id,['name'=>$u->name,'email'=>$u->email,'role'=>'editor','active'=>1])->assertSessionHasErrors('role');$this->delete('/admin/users/'.$u->id)->assertSessionHasErrors('active');$this->put('/admin/users/'.$u->id,['name'=>$u->name,'email'=>$u->email,'role'=>'administrator','active'=>0])->assertSessionHasErrors('active');$this->assertTrue($u->fresh()->isAdministrator());}
 public function test_soft_deletion_preserves_posts_and_restores_inactive():void {$a=$this->staff();$p=$this->article();$u=$p->author;$this->actingAs($a)->delete('/admin/users/'.$u->id)->assertRedirect();$this->assertSoftDeleted('users',['id'=>$u->id]);$this->assertSame($u->id,$p->fresh()->author_id);$this->post('/admin/users/'.$u->id.'/restore')->assertRedirect();$this->assertFalse($u->fresh()->active);}
 public function test_inactive_account_cannot_login_or_continue_session():void {$u=$this->staff('editor');$this->actingAs($u);$u->active=false;$u->save();$this->get('/admin')->assertRedirect('/login');$this->assertGuest();$this->post('/login',['email'=>$u->email,'password'=>'password'])->assertSessionHasErrors('email');}
 public function test_editor_can_create_draft_but_invalid_publish_is_rejected():void {$u=$this->staff('editor');$this->actingAs($u);$data=['title'=>'मराठी लेख','author_id'=>$u->id,'status'=>'draft','language'=>'mr','schema_mode'=>'automatic'];$this->post('/admin/blogs',$data)->assertRedirect();$p=Post::firstOrFail();$this->assertSame('मराठी लेख',$p->title);$this->put('/admin/blogs/'.$p->id,array_merge($data,['version'=>$p->version,'status'=>'published']))->assertSessionHasErrors(['body_html','category_id']);}
 public function test_drafts_future_schedules_and_trash_do_not_leak():void {$draft=$this->article(['slug'=>'draft','status'=>'draft']);$future=$this->article(['slug'=>'future','status'=>'scheduled','published_at'=>now()->addHour()]);$trash=$this->article(['slug'=>'trash']);$trash->delete();foreach([$draft,$future,$trash] as $p)$this->get('/blog/'.$p->slug)->assertNotFound();$this->get('/blog')->assertOk()->assertDontSee('href="'.$future->public_url.'"',false);$this->get('/sitemap.xml')->assertOk()->assertDontSee($future->public_url)->assertDontSee($draft->public_url)->assertDontSee($trash->public_url);}
 public function test_schedule_boundary_is_consistent():void {$this->travelTo(now()->startOfMinute());$p=$this->article(['status'=>'scheduled','published_at'=>now()->addMinute()]);$this->get('/blog/'.$p->slug)->assertNotFound();$this->travel(1)->minutes();$this->get('/blog/'.$p->slug)->assertOk();$this->get('/sitemap.xml')->assertSee($p->public_url);$this->assertSame('published',$p->effective_status);}
 public function test_ist_input_is_stored_as_utc():void {$p=$this->article();$this->actingAs($p->author);$this->put('/admin/blogs/'.$p->id,$this->payload($p,['status'=>'scheduled','published_at'=>'2030-01-01T10:30']))->assertRedirect();$this->assertSame('2030-01-01 05:00',$p->fresh()->published_at->format('Y-m-d H:i'));}
 public function test_published_slug_redirect_is_direct_and_namespace_reserved():void {$p=$this->article();$this->actingAs($p->author);$this->put('/admin/blogs/'.$p->id,$this->payload($p,['status'=>'published','slug'=>'new-story']))->assertRedirect();$this->get('/blog/a-thoughtful-story')->assertRedirect('/blog/new-story')->assertStatus(301);$other=$this->article(['slug'=>'another']);$this->put('/admin/blogs/'.$other->id,$this->payload($other,['slug'=>'a-thoughtful-story']))->assertSessionHasErrors('slug');$this->put('/admin/blogs/'.$p->id,$this->payload($p->fresh(),['slug'=>'a-thoughtful-story','status'=>'published']))->assertRedirect();$this->get('/blog/new-story')->assertStatus(301)->assertRedirect('/blog/a-thoughtful-story');}
 public function test_autosave_never_modifies_published_post_and_conflict_detected():void {$p=$this->article();$original=$p->body_html;$this->actingAs($p->author);$this->post('/admin/blogs/'.$p->id.'/autosave',$this->payload($p,['body_html'=>'<p>Private unfinished edit</p>']))->assertOk();$this->assertSame($original,$p->fresh()->body_html);$this->assertDatabaseCount('post_working_copies',1);$this->put('/admin/blogs/'.$p->id,$this->payload($p,['title'=>'New saved title']))->assertRedirect();$this->postJson('/admin/blogs/'.$p->id.'/autosave',$this->payload($p))->assertStatus(409);$this->put('/admin/blogs/'.$p->id,$this->payload($p))->assertSessionHasErrors('version');$this->assertDatabaseCount('post_revisions',1);}
 public function test_revision_restoration_is_draft_and_records_previous_state():void {$p=$this->article();$this->actingAs($p->author);$this->put('/admin/blogs/'.$p->id,$this->payload($p,['title'=>'Changed title']))->assertRedirect();$id=DB::table('post_revisions')->value('id');$this->post('/admin/blogs/'.$p->id.'/revision/'.$id,['version'=>$p->fresh()->version])->assertRedirect();$this->assertSame('A thoughtful story',$p->fresh()->title);$this->assertSame('draft',$p->fresh()->status);}
 public function test_sanitizer_preserves_semantics_and_removes_execution():void {$html='<h2>मराठी Heading</h2><p><strong>Bold</strong> <em>italic</em> <u>underline</u></p><ol><li>First</li></ol><ul><li>Bullet</li></ul><blockquote>Quote</blockquote><hr><script>alert(1)</script><p onclick="bad()">Safe <a href="javascript:alert(1)">bad</a><a href="https://example.com">good</a></p><iframe src="https://bad.test"></iframe>';$safe=app(ArticleContent::class)->sanitize($html);foreach(['<h2','<strong>','<em>','<u>','<ol>','<ul>','<blockquote>','<hr','मराठी'] as $token)$this->assertStringContainsString($token,$safe);foreach(['<script','onclick','javascript:','<iframe'] as $token)$this->assertStringNotContainsString($token,$safe);}
 public function test_rich_content_save_reopen_and_public_render():void {$p=$this->article();$this->actingAs($p->author);$body='<h2>Meaningful heading</h2><p><strong>Emphasis</strong> and <u>underlining</u> preserved with enough article text for publication.</p><blockquote>A real quote</blockquote>';$this->put('/admin/blogs/'.$p->id,$this->payload($p,['body_html'=>$body,'body_delta'=>'{"ops":[{"insert":"Meaningful heading"}]}','status'=>'published']))->assertRedirect();$this->get('/admin/blogs/'.$p->id.'/edit')->assertOk()->assertSee('Meaningful heading');$this->get('/blog/'.$p->slug)->assertSee('<strong>Emphasis</strong>',false)->assertSee('<blockquote>',false);}
 public function test_image_upload_reencodes_and_private_unused_media_is_hidden():void {Storage::fake('local');$this->actingAs($this->staff('editor'));$r=$this->postJson('/admin/media',['image'=>UploadedFile::fake()->image('image.png',100,100),'alt'=>'A meaningful illustration']);$r->assertCreated();$m=Media::firstOrFail();$this->assertMatchesRegularExpression('/^[a-f0-9]{40}\.png$/',$m->filename);Storage::disk('local')->assertExists('blog-media/'.$m->filename);$this->postJson('/admin/media',['image'=>UploadedFile::fake()->create('evil.php',2,'application/x-php'),'alt'=>'bad'])->assertUnprocessable();$this->post('/logout');$this->get('/media/'.$m->filename)->assertNotFound();}
 public function test_taxonomy_management_and_referenced_deletion_guard():void {$p=$this->article();$this->actingAs($p->author);$this->delete('/admin/taxonomy/categories/'.$p->category_id)->assertSessionHasErrors('taxonomy');$this->post('/admin/taxonomy/tags',['name'=>'New tag'])->assertRedirect();$tag=Tag::firstOrFail();$this->post('/admin/taxonomy/tags',['name'=>'New tag'])->assertSessionHasErrors('name');$this->delete('/admin/taxonomy/tags/'.$tag->id)->assertRedirect();}
 public function test_filters_sorting_pagination_and_trash_restore():void {$p=$this->article();$this->actingAs($p->author);$this->get('/admin/blogs?q=thoughtful&sort=title&direction=asc')->assertOk()->assertSee($p->title);$this->get('/admin/blogs?sort=bad%20sql')->assertOk();$this->delete('/admin/blogs/'.$p->id)->assertRedirect();$this->post('/admin/blogs/'.$p->id.'/restore')->assertRedirect();$this->assertSame('draft',$p->fresh()->status);}
 public function test_bulk_publish_validates_every_record_atomically():void {$p=$this->article(['status'=>'draft']);$bad=$this->article(['slug'=>'incomplete','status'=>'draft','body_html'=>'']);$this->actingAs($p->author)->post('/admin/blogs/bulk',['ids'=>[$p->id,$bad->id],'action'=>'publish'])->assertSessionHasErrors('body_html');$this->assertSame('draft',$p->fresh()->status);}
 public function test_automatic_schema_and_safe_encoding():void {$p=$this->article(['title'=>'A </script><script>alert(1)</script> title']);$data=app(ArticleSchema::class)->encoded($p);$this->assertStringNotContainsString('</script>',$data);$decoded=json_decode($data,true);$this->assertSame('BlogPosting',$decoded['@graph'][0]['@type']);$this->assertSame($p->canonical,$decoded['@graph'][0]['url']);$this->assertSame('BreadcrumbList',$decoded['@graph'][1]['@type']);}
 public function test_manual_schema_empty_invalid_and_consistency():void {$p=$this->article(['schema_mode'=>'manual','manual_schema'=>'']);$s=app(ArticleSchema::class);$this->assertSame('Automatic',$s->effective($p)['source']);$p->manual_schema=json_encode(['@context'=>'https://schema.org','@type'=>'BlogPosting','headline'=>$p->title,'url'=>$p->canonical]);$this->assertSame('Manual',$s->effective($p)['source']);$this->actingAs($p->author);$this->put('/admin/blogs/'.$p->id,$this->payload($p,['status'=>'published','schema_mode'=>'manual','manual_schema'=>'{invalid']))->assertSessionHasErrors('manual_schema');$this->put('/admin/blogs/'.$p->id,$this->payload($p,['status'=>'draft','schema_mode'=>'manual','manual_schema'=>'{invalid']))->assertRedirect();}
 public function test_schema_duplicates_and_mismatched_manual_headline_rejected():void {$p=$this->article();$this->expectException(\Illuminate\Validation\ValidationException::class);app(ArticleSchema::class)->manual(json_encode(['@type'=>'BlogPosting','headline'=>'Wrong','url'=>$p->canonical]),$p);}
 public function test_metadata_changes_do_not_modify_article_lastmod():void {$p=$this->article();$time=$p->content_updated_at->toIso8601String();$this->actingAs($p->author);$this->put('/admin/blogs/'.$p->id,$this->payload($p,['status'=>'published','seo_title'=>'New metadata']))->assertRedirect();$this->assertSame($time,$p->fresh()->content_updated_at->toIso8601String());}
 public function test_seo_canonical_and_sitemap_exclusions():void {$p=$this->article(['noindex'=>true]);$this->get('/blog/'.$p->slug)->assertSee('noindex,follow')->assertSee('rel="canonical"',false);$this->get('/sitemap.xml')->assertDontSee($p->public_url);$p->update(['noindex'=>false,'canonical_url'=>'https://example.test/original']);$this->get('/sitemap.xml')->assertDontSee($p->public_url);}
 public function test_comments_pending_privacy_and_disabled_guard():void {$p=$this->article(['comments_enabled'=>true]);$this->post('/blog/'.$p->slug.'/comments',['name'=>'Reader','email'=>'private@example.test','body'=>'A thoughtful comment'])->assertRedirect();$c=Comment::firstOrFail();$this->assertSame('pending',$c->status);$this->get('/blog/'.$p->slug)->assertDontSee('A thoughtful comment')->assertDontSee('private@example.test');$c->update(['status'=>'approved']);$this->get('/blog/'.$p->slug)->assertSee('A thoughtful comment')->assertDontSee('private@example.test');$p->update(['comments_enabled'=>false]);$this->post('/blog/'.$p->slug.'/comments',[])->assertNotFound();}
 public function test_comment_html_honeypot_validation_and_throttle():void {$p=$this->article(['comments_enabled'=>true]);$url='/blog/'.$p->slug.'/comments';$data=['name'=>'Reader','email'=>'r@example.test','body'=>'<script>alert(1)</script>'];$this->post($url,$data)->assertSessionHasErrors('body');$this->post($url,array_merge($data,['website'=>'spam']))->assertSessionHasErrors('website');$this->post($url,['name'=>''])->assertSessionHasErrors();$this->post($url,$data)->assertStatus(429);}
 public function test_comment_moderation_bulk_authorized_and_recoverable():void {$p=$this->article();$c=Comment::create(['post_id'=>$p->id,'name'=>'Reader','email'=>'r@example.test','body'=>'A useful comment','status'=>'pending']);$this->actingAs($this->staff('editor'));foreach(['approved','trash','restore'] as $action)$this->post('/admin/comments/moderate',['ids'=>[$c->id],'action'=>$action,'confirm'=>1])->assertRedirect();$this->assertSame('approved',$c->fresh()->status);}
 public function test_script_configuration_never_executes_and_activation_blocked():void {$p=$this->article();$this->actingAs($p->author);$data=['name'=>'Analytics','placement'=>'head','configuration'=>'{"provider":"google-analytics","measurement_id":"G-ABC123456"}','consent'=>'analytics','enabled'=>0];$this->post('/admin/blogs/'.$p->id.'/scripts',$data)->assertRedirect();$this->assertDatabaseHas('blog_scripts',['post_id'=>$p->id,'enabled'=>false]);$this->post('/admin/blogs/'.$p->id.'/scripts',array_merge($data,['enabled'=>1]))->assertSessionHasErrors('scripts');$this->get('/blog/'.$p->slug)->assertDontSee('googletagmanager');$this->get('/admin/blogs/'.$p->id.'/preview')->assertHeader('X-Robots-Tag','noindex, nofollow, noarchive')->assertDontSee('googletagmanager');}
 public function test_all_main_blade_screens_render():void {$p=$this->article();$this->actingAs($p->author);foreach(['/admin','/admin/users','/admin/users/create','/admin/users/'.$p->author_id,'/admin/users/'.$p->author_id.'/edit','/admin/blogs','/admin/blogs/create','/admin/blogs/'.$p->id,'/admin/blogs/'.$p->id.'/edit','/admin/comments','/admin/taxonomy/categories','/admin/taxonomy/tags'] as $path)$this->get($path)->assertOk();}
 public function test_new_staff_defaults_active_and_date_filters_use_ist():void {$u=$this->staff();$p=$this->article(['created_at'=>'2030-01-01 20:00:00']);$this->actingAs($u);$this->get('/admin/users/create')->assertSee('value="1" selected',false);$this->get('/admin/blogs?from=2030-01-02&to=2030-01-02')->assertSee($p->title);$this->get('/admin/blogs?from=2030-01-01&to=2030-01-01')->assertDontSee($p->title);}
 public function test_deleted_author_can_be_retained_during_content_edit():void {$p=$this->article();$u=$p->author;$u->delete();$this->actingAs($this->staff());$this->get('/admin/blogs/'.$p->id.'/edit')->assertSee($u->name);$this->put('/admin/blogs/'.$p->id,$this->payload($p))->assertRedirect();$this->assertSame($u->id,$p->fresh()->author_id);}
 public function test_manual_schema_rejects_duplicate_article_nodes():void {$p=$this->article();$node=['@type'=>'BlogPosting','headline'=>$p->title,'url'=>$p->canonical];$this->expectException(\Illuminate\Validation\ValidationException::class);app(ArticleSchema::class)->manual(json_encode(['@context'=>'https://schema.org','@graph'=>[$node,$node]]),$p);}
 public function test_editor_cannot_smuggle_script_configuration_in_post_update():void {$p=$this->article();$this->actingAs($this->staff('editor'))->put('/admin/blogs/'.$p->id,$this->payload($p,['script_code'=>'alert(1)']))->assertSessionHasErrors('script_code');$this->assertDatabaseCount('blog_scripts',0);}
 public function test_uploaded_figure_caption_and_alt_survive_sanitization():void {$u=$this->staff();$m=Media::create(['user_id'=>$u->id,'filename'=>str_repeat('a',40).'.png','mime'=>'image/png','bytes'=>500,'width'=>100,'height'=>100,'alt'=>'Original alt']);$html='<figure><img src="'.$m->url.'" alt="Meaningful alt" onerror="alert(1)"><figcaption>मराठी caption</figcaption></figure>';$safe=app(ArticleContent::class)->sanitize($html);$this->assertStringContainsString('<figure>',$safe);$this->assertStringContainsString('Meaningful alt',$safe);$this->assertStringContainsString('मराठी caption',$safe);$this->assertStringNotContainsString('onerror',$safe);}
}
